"""Write the tuned configuration file and the tuning summary for the report."""

from __future__ import annotations

from pathlib import Path

import yaml

from recsys.experiments.config import ExperimentConfig
from recsys.experiments.report import DISPLAY_NAMES
from recsys.tuning.tuner import TuningResult, load_study, param_importance

TUNED_HEADER = """\
# GENERATED by `recsys tune` from {source}: do not edit by hand.
# Best validation hyperparameters per model (Optuna, equal time budget per model; see
# docs/results/{dataset}/tuning/README.md). Models without a search space keep their defaults.
"""


def write_tuned_config(
    cfg: ExperimentConfig, results: list[TuningResult], minutes: float, max_trials: int
) -> Path:
    """Create or update <dataset>-tuned.yaml: tuned entries replace their defaults, others are kept."""
    assert cfg.source is not None
    out = cfg.source.with_name(f"{cfg.source.stem}-tuned.yaml")
    raw = yaml.safe_load(cfg.source.read_text(encoding="utf-8"))
    if out.exists():  # keep entries tuned in earlier sessions
        previous = yaml.safe_load(out.read_text(encoding="utf-8"))
        raw["models"].update(previous.get("models", {}))
    for r in results:
        raw["models"][r.entry] = r.best_params
    raw["description"] = (
        f"Tuned on the validation set with Optuna (TPE), equal budget per model: at most {max_trials} trials "
        f"or {minutes:g} minutes, trial 0 = paper defaults. Test data was never used for tuning."
    )
    text = TUNED_HEADER.format(source=cfg.source.name, dataset=cfg.dataset)
    out.write_text(
        text + yaml.safe_dump(raw, sort_keys=False, default_flow_style=None, width=110), encoding="utf-8"
    )
    return out


def tuning_markdown(
    cfg: ExperimentConfig, fingerprint: str, entries: list[str], minutes: float, max_trials: int
) -> str:
    """Summary table rebuilt from the Optuna database (the record of every trial)."""
    lines = [
        f"# Hyperparameter tuning: {cfg.dataset}",
        "",
        f"Objective: validation {cfg.primary_metric} (test data never used). Sampler: TPE; median pruning "
        f"for iterative models. Budget per model: at most {max_trials} trials or {minutes:g} minutes of "
        "wall-clock time on the same 4-core laptop CPU. Trial 0 = paper defaults, so 'best' is never "
        "below 'default'.",
        "",
        "| Model | Trials (complete / pruned) | Default val | Best val | Gain | Best parameters |",
        "|---|---:|---:|---:|---:|---|",
    ]
    importances = []
    for entry in entries:
        study = load_study(cfg.dataset, fingerprint, entry)
        if study is None:
            continue
        complete = [t for t in study.trials if t.state.name == "COMPLETE"]
        pruned = [t for t in study.trials if t.state.name == "PRUNED"]
        if not complete:
            continue
        default = next((t.value for t in complete if t.number == 0), None)
        best = max(complete, key=lambda t: t.value)
        gain = f"{(best.value / default - 1):+.1%}" if default else "n/a"
        params = ", ".join(f"{k}={_fmt(v)}" for k, v in best.params.items())
        name = DISPLAY_NAMES.get(entry, entry)
        cells = [
            name,
            f"{len(complete)} / {len(pruned)}",
            _fmt(default),
            f"**{best.value:.4f}**",
            gain,
            params,
        ]
        lines.append("| " + " | ".join(cells) + " |")
        imp = param_importance(study)
        if imp:
            importances.append(f"| {name} | " + ", ".join(f"{k} {v:.2f}" for k, v in imp.items()) + " |")
    if importances:
        lines += [
            "",
            "## Which hyperparameters mattered (PED-ANOVA importance, sums to 1)",
            "",
            "| Model | Importance |",
            "|---|---|",
            *importances,
        ]
    return "\n".join(lines) + "\n"


def _fmt(v) -> str:
    if v is None:
        return "n/a"
    if isinstance(v, float):
        return f"{v:.4g}" if abs(v) < 1e-2 or abs(v) >= 1e3 else f"{v:.4f}".rstrip("0").rstrip(".")
    return str(v)
